// VITE_API_BASE_URL is an origin only (scheme + host + optional port).
// The versioned API prefix belongs to this client and is added exactly once.
export function normalizeApiOrigin(value = '') {
  const raw = String(value || '').trim().replace(/\/+$/, '');
  if (!raw) return '';
  let parsed;
  try { parsed = new URL(raw); }
  catch { throw new Error('VITE_API_BASE_URL must be a backend origin, e.g. http://localhost:8000 (without /api/v1).'); }
  if (!['http:', 'https:'].includes(parsed.protocol) || parsed.pathname !== '' && parsed.pathname !== '/' || parsed.search || parsed.hash) {
    throw new Error('VITE_API_BASE_URL must contain only the backend origin, e.g. http://localhost:8000. Do not include /api/v1 or an API path.');
  }
  return parsed.origin;
}

export function buildApiUrl(origin, path) {
  if (typeof path !== 'string' || !path.startsWith('/') || path.startsWith('/api/v1/')) {
    throw new Error(`API endpoint must be a versionless absolute path, received: ${path}`);
  }
  return `${origin.replace(/\/+$/, '')}/api/v1${path}`;
}

